#!/usr/bin/env node
/**
 * Fails if any maintained text file in the repository contains an em dash (U+2014).
 *
 *   npm run check:text
 *
 * Scans source, styles, docs, configuration and data files. Skips dependencies, build output,
 * lockfiles, binary files and generated files (listed in SKIP_FILES with the reason).
 * To fix a failure, rewrite the sentence with a comma, colon, period, parentheses or a hyphen.
 */
import { readdirSync, readFileSync, statSync } from "node:fs";
import path from "node:path";

const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), "..");
const EM_DASH = String.fromCharCode(0x2014);
const SKIP_DIRS = new Set(["node_modules", ".next", ".git", "out", "build", "coverage", ".vercel", "uploads", "__pycache__", ".pytest_cache", ".venv", "venv"]);
const SKIP_FILES = new Set([
  "package-lock.json", // generated by npm
  "next-env.d.ts", // generated by Next.js
]);
const TEXT_EXT = new Set([".ts", ".tsx", ".js", ".mjs", ".cjs", ".jsx", ".json", ".md", ".mdx", ".css", ".scss", ".html", ".txt", ".yml", ".yaml", ".toml", ".py", ".env", ".example", ".svg", ".sh"]);
const TEXT_NAMES = new Set(["Dockerfile", ".dockerignore", ".gitignore", "LICENSE"]);

const hits = [];
function walk(dir) {
  for (const name of readdirSync(dir)) {
    if (SKIP_DIRS.has(name)) continue;
    const full = path.join(dir, name);
    const st = statSync(full);
    if (st.isDirectory()) {
      walk(full);
      continue;
    }
    if (SKIP_FILES.has(name)) continue;
    if (!TEXT_EXT.has(path.extname(name)) && !TEXT_NAMES.has(name)) continue;
    if (st.size > 5 * 1024 * 1024) continue;
    const text = readFileSync(full, "utf8");
    if (!text.includes(EM_DASH)) continue;
    text.split("\n").forEach((line, i) => {
      if (line.includes(EM_DASH)) hits.push(`${path.relative(ROOT, full)}:${i + 1}: ${line.trim().slice(0, 140)}`);
    });
  }
}

walk(ROOT);
if (hits.length) {
  console.error(`Found ${hits.length} em dash${hits.length === 1 ? "" : "es"} (U+2014). Rewrite these lines without them:\n`);
  for (const h of hits) console.error(`  ${h}`);
  process.exit(1);
}
console.log("No em dashes found in maintained text files.");
